    console.log('DEBUG ===== BUILD ALGORITHM: PROCESSING HIGHEST PRIORITY EVENTS =====');
    console.log(`DEBUG Total Highest Priority Events to check: ${highestPriorityEvents.length}`);
    console.log(`DEBUG Build Date: ${buildDate}`);
    
    let includedCount = 0;
